// Escolhe a tela pela rota (#/...). Telas que precisam de login (RN-01) mandam
// o visitante para "Entrar" e voltam para onde ele estava.
import { useEffect } from "react";
import { Carregando } from "./componentes";
import { ProvedorCarrinho } from "./contextos/Carrinho";
import { ProvedorSessao, useSessao } from "./contextos/Sessao";
import { caminhoDe, ir, Rota, useRota } from "./navegacao";
import Cadastro from "./paginas/Cadastro";
import Cardapio from "./paginas/Cardapio";
import Checkout from "./paginas/Checkout";
import DetalheItem from "./paginas/DetalheItem";
import EmBreve from "./paginas/EmBreve";
import Entrar from "./paginas/Entrar";
import Inicio from "./paginas/Inicio";
import PedidoRecebido from "./paginas/PedidoRecebido";
import Sacola from "./paginas/Sacola";

const EXIGEM_LOGIN: Rota["tela"][] = ["sacola", "checkout", "pedido-recebido"];

function Telas() {
  const rota = useRota();
  const { cliente, carregando } = useSessao();
  const bloqueada = EXIGEM_LOGIN.includes(rota.tela) && !cliente;

  useEffect(() => {
    if (!carregando && bloqueada) ir({ tela: "entrar", depois: caminhoDe(rota).slice(1) }, { substituir: true });
  }, [carregando, bloqueada, rota]);

  if (carregando || bloqueada) return <div className="tela"><Carregando /></div>;

  switch (rota.tela) {
    case "entrar":
      return <Entrar depois={rota.depois} />;
    case "cadastro":
      return <Cadastro />;
    case "cardapio":
      return <Cardapio />;
    case "item":
      return <DetalheItem key={rota.produtoId} produtoId={rota.produtoId} />;
    case "sacola":
      return <Sacola />;
    case "checkout":
      return <Checkout />;
    case "pedido-recebido":
      return <PedidoRecebido pedidoId={rota.pedidoId} />;
    case "pedidos":
    case "fidelidade":
      return <EmBreve aba={rota.tela} />;
    default:
      return <Inicio />;
  }
}

export default function App() {
  return (
    <ProvedorSessao>
      <ProvedorCarrinho>
        <div className="app">
          <Telas />
        </div>
      </ProvedorCarrinho>
    </ProvedorSessao>
  );
}
"""Montagem do carrinho com valores sempre recalculados (UC29 passos 1–3, RF-13).

Cada vez que o carrinho é devolvido ao cliente:
1. tenta atualizar o cardápio da unidade no SGL; se falhar, usa o último salvo
   e informa o horário dele (UC29 E3, RNF-03);
2. retira itens que saíram do cardápio e avisa (UC29 E2);
3. recalcula cada item com o preço e o desconto vigentes (RF-02, RF-11, RF-13)
   e grava os valores recalculados na linha de `item_pedido`.
"""

import sqlite3

from .. import relogio
from . import cardapio, precos


def obter(conn: sqlite3.Connection, cliente_id: int) -> sqlite3.Row | None:
    return conn.execute("SELECT * FROM carrinho WHERE cliente_id = ?", (cliente_id,)).fetchone()


def tocar(conn: sqlite3.Connection, carrinho_id: int) -> None:
    conn.execute("UPDATE carrinho SET atualizado_em = ? WHERE id = ?",
                 (relogio.para_texto(relogio.agora()), carrinho_id))


def contar_itens(conn: sqlite3.Connection, carrinho_id: int) -> int:
    return conn.execute("SELECT COUNT(*) FROM item_pedido WHERE carrinho_id = ?", (carrinho_id,)).fetchone()[0]


def gravar_valores(conn: sqlite3.Connection, item_id: int, quantidade: int, produto: dict) -> int:
    """RF-13: grava na linha do carrinho o preço, o desconto e o valor final
    vigentes (RF-02). Devolve o valor final."""
    valor = precos.valor_final(quantidade, produto["preco_centavos"], produto["desconto_centavos"])
    conn.execute(
        """UPDATE item_pedido SET quantidade = ?, preco_unitario_centavos = ?,
               desconto_unitario_centavos = ?, valor_final_centavos = ?
           WHERE id = ? AND carrinho_id IS NOT NULL""",
        (quantidade, produto["preco_centavos"], produto["desconto_centavos"], valor, item_id),
    )
    return valor


def inserir(conn: sqlite3.Connection, carrinho_id: int, quantidade: int, observacao: str | None,
            produto: dict) -> None:
    valor = precos.valor_final(quantidade, produto["preco_centavos"], produto["desconto_centavos"])
    conn.execute(
        """INSERT INTO item_pedido (carrinho_id, item_cardapio_id, quantidade, observacao,
               preco_unitario_centavos, desconto_unitario_centavos, valor_final_centavos)
           VALUES (?, ?, ?, ?, ?, ?, ?)""",
        (carrinho_id, produto["id"], quantidade, observacao,
         produto["preco_centavos"], produto["desconto_centavos"], valor),
    )


def _vazio() -> dict:
    return {"unidade": None, "itens": [], "subtotal_centavos": 0, "avisos": [],
            "cardapio_atualizado_em": None, "sgl_indisponivel": False}


def montar(conn: sqlite3.Connection, cliente_id: int) -> dict:
