// Tira os prints das telas do BurguerJá (versão 96e2202) em 390x844.
const { chromium } = require('/home/mfigueireddo/Git/personal-use/node_modules/playwright');
const fs = require('fs');
const path = require('path');

const S = __dirname;
const OUT = path.join(S, 'shots');
const BASE = 'http://localhost:5180/';
const JSON_CARD = path.join(S, 'app/backend/app/integracoes/dados_simulados/cardapios_sgl.json');
fs.mkdirSync(OUT, { recursive: true });
const etapa = process.argv[2] || 'all';

(async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, locale: 'pt-BR' });
  const page = await ctx.newPage();
  const shot = async (nome) => { await page.waitForTimeout(700); await page.screenshot({ path: path.join(OUT, nome + '.png') }); console.log('ok', nome); };
  const go = async (hash) => { await page.goto(BASE + hash); await page.waitForTimeout(800); };

  // ---- Infra
  await go('#/entrar');
  await shot('01-entrar');
  await page.getByLabel('E-mail').fill('[email-removido]');
  await page.getByLabel('Senha').fill('errada123');
  await page.getByRole('button', { name: 'Entrar', exact: true }).click();
  await shot('02-login-erro');
  await go('#/cadastro');
  await shot('03-cadastro');
  await go('#/entrar');
  await page.getByLabel('E-mail').fill('[email-removido]');
  await page.getByLabel('Senha').fill('demo1234');
  await page.getByRole('button', { name: 'Entrar', exact: true }).click();
  await page.waitForTimeout(1000);
  await go('#/');
  await shot('04-inicio');
  await page.getByText('BurguerJá Gávea').first().click();
  await page.waitForTimeout(1000);
  await shot('05-cardapio');

  // ---- UC29
  await page.getByText('Burguer Clássico').first().click();
  await page.waitForTimeout(800);
  await page.getByLabel('Aumentar quantidade').click();
  await page.getByLabel('Observação').fill('sem cebola');
  await shot('06-detalhe');
  await page.getByRole('button', { name: /Adicionar/ }).click();
  await page.waitForTimeout(800);
  await go('#/cardapio');
  await page.getByText('Batata frita média').first().click();
  await page.waitForTimeout(600);
  await page.getByRole('button', { name: /Adicionar/ }).click();
  await page.waitForTimeout(600);
  await go('#/cardapio');
  await page.getByText('Combo Clássico').first().click();
  await page.waitForTimeout(600);
  await page.getByRole('button', { name: /Adicionar/ }).click();
  await page.waitForTimeout(600);
  await go('#/cardapio');
  await shot('07-cardapio-barra-sacola');
  await go('#/sacola');
  await shot('08-sacola');

  // E2 + RF-13: tira a batata do SGL e muda o preço do burguer
  const original = fs.readFileSync(JSON_CARD, 'utf8');
  try {
    const d = JSON.parse(original);
    d['UN-GAVEA'].itens = d['UN-GAVEA'].itens.filter((i) => i.id_sgl !== 'ACO-01');
    for (const i of d['UN-GAVEA'].itens) if (i.id_sgl === 'LAN-01') i.preco_centavos = 2790;
    fs.writeFileSync(JSON_CARD, JSON.stringify(d, null, 2));
    await go('#/sacola');
    await page.reload(); await page.waitForTimeout(1200);
    await shot('09-sacola-item-removido');
  } finally {
    fs.writeFileSync(JSON_CARD, original);
  }

  // Outra unidade
  await go('#/');
  await page.getByText('BurguerJá Botafogo').first().click();
  await page.waitForTimeout(800);
  await page.getByText('Burguer Clássico').first().click();
  await page.waitForTimeout(600);
  await page.getByRole('button', { name: /Adicionar/ }).click();
  await page.waitForTimeout(800);
  await shot('10-outra-unidade');
  await page.getByRole('button', { name: 'Manter minha sacola' }).click();
  await page.waitForTimeout(400);

  // ---- UC28 (sacola da Gávea)
  await go('#/checkout');
  await page.waitForTimeout(1200);
  await shot('11-checkout-entrega');
  await page.screenshot({ path: path.join(OUT, '11b-checkout-entrega-full.png'), fullPage: true });
  await page.getByText('Retirada', { exact: false }).first().click();
  await page.waitForTimeout(1000);
  await shot('12-checkout-retirada');
  await page.getByText('Entrega', { exact: false }).first().click();
  await page.waitForTimeout(800);
  // confirmar
  await page.getByRole('button', { name: /Confirmar|Fazer pedido|Finalizar/ }).last().click();
  await page.waitForTimeout(1500);
  await shot('13-pedido-recebido');

  // Fora do raio: sacola na Botafogo + endereço da PUC
  await go('#/');
  await page.getByText('BurguerJá Botafogo').first().click();
  await page.waitForTimeout(800);
  await page.getByText('Burguer Clássico').first().click();
  await page.waitForTimeout(600);
  await page.getByRole('button', { name: /Adicionar/ }).click();
  await page.waitForTimeout(800);
  await go('#/checkout');
  await page.waitForTimeout(1200);
  await page.getByText('Marquês de São Vicente').first().click().catch(() => {});
  await page.waitForTimeout(1200);
  await shot('14-fora-do-raio');
  await page.getByText('Drive-thru', { exact: false }).first().click().catch(() => {});
  await page.waitForTimeout(1000);
  await shot('15-drive-thru');

  // Sacola: confirmar esvaziar e vazia
  await go('#/sacola');
  await page.getByRole('button', { name: 'Esvaziar sacola' }).click();
  await page.waitForTimeout(500);
  await shot('16-esvaziar');
  await page.getByRole('button', { name: /Esvaziar/ }).last().click();
  await page.waitForTimeout(800);
  await shot('17-sacola-vazia');

  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

