:root {
  --paper: #FBF7F0;
  --cream: #F3E7D3;
  --line: #E2D3B8;
  --ink: #1F1A17;
  --soft: #5A4E45;
  --red: #C2261B;
  --yellow: #FFC72C;
}

section {
  background: var(--paper);
  color: var(--ink);
  font-family: 'Inter', Arial, sans-serif;
  padding: 128px;
}

h1, h2, h3 { font-family: 'Rubik', Arial, sans-serif; color: var(--ink); }

/* ---------- capa ---------- */
.cover { background: var(--ink); display: flex; flex-direction: column; justify-content: center; gap: 40px; }
.cover .tag { font-size: 28px; font-weight: 600; color: var(--yellow); letter-spacing: 3px; }
.cover h1 { font-size: 120px; line-height: 1.02; font-weight: 700; color: var(--paper); }
.cover .sub { font-size: 36px; line-height: 1.35; color: #D9CFC4; width: 1200px; }
.cover .meta { font-size: 26px; color: #B9ADA1; }
