// Gera o PDF do deck (1920x1080 por página) a partir do page.html do preview.
const { chromium } = require('/home/mfigueireddo/Git/personal-use/node_modules/playwright');
const fs = require('fs');
const out = process.argv[2];
(async () => {
  const extra = `<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Rubik:wght@400..700&family=Inter:wght@400;600&display=swap">
<style>@page { size: 1920px 1080px; margin: 0 } body { margin: 0 } body > section { break-after: page }</style></head>`;
  const html = fs.readFileSync(__dirname + '/page.html', 'utf8').replace('</head>', extra);
  fs.writeFileSync(__dirname + '/pdf.html', html);
  const b = await chromium.launch({ args: ['--allow-file-access-from-files'] });
  const p = await (await b.newContext({ javaScriptEnabled: false })).newPage();
  await p.goto('file://' + __dirname + '/pdf.html', { waitUntil: 'networkidle' });
  await p.evaluate(() => document.fonts.ready);
  const fontes = await p.evaluate(() => [...document.fonts].filter((f) => f.status === 'loaded').map((f) => f.family));
  console.log('fontes carregadas:', [...new Set(fontes)].join(', ') || 'nenhuma');
  await p.pdf({ path: out, width: '1920px', height: '1080px', printBackground: true, preferCSSPageSize: true });
  await b.close();
})();

